export DIR=$(mktemp -d)
node --import tsx -e '
import { createApp } from "./src/server.ts";
const app = createApp(process.env.DIR);
const server = app.listen(0, async () => {
  const port = server.address().port;
  const base = `http://127.0.0.1:${port}`;
  const tests = [
    ["PUT encoded traversal (../secret.txt)", `${base}/blobs/%2e%2e%2fsecret.txt`, "PUT"],
    ["PUT plain traversal segment (a/../../secret.txt)", `${base}/blobs/a/../../secret.txt`, "PUT"],
    ["PUT absolute-looking (//etc/passwd)", `${base}/blobs//etc/passwd`, "PUT"],
    ["PUT harmless internal .. that stays inside root (a/../b.txt)", `${base}/blobs/a/../b.txt`, "PUT"],
    ["PUT literal filename with dots (my..file.txt)", `${base}/blobs/my..file.txt`, "PUT"],
    ["GET malformed pct incomplete", `${base}/blobs/%E0%A4%A`, "GET"],
    ["DELETE encoded traversal", `${base}/blobs/%2e%2e%2fsecret.txt`, "DELETE"],
    ["PUT just ..", `${base}/blobs/..`, "PUT"],
    ["PUT null byte %00", `${base}/blobs/foo%00bar`, "PUT"],
  ];
  for (const [label, url, method] of tests) {
    try {
      const res = await fetch(url, { method, body: method === "PUT" ? "x" : undefined });
      const text = await res.text().catch(() => "");
      console.log(label, "->", res.status, JSON.stringify(text).slice(0,150));
    } catch (e) {
      console.log(label, "-> request error:", e.message);
    }
  }
  server.close();
});
' 2>&1
echo "---- files that ended up outside/inside dataDir ----"
find "$DIR" -maxdepth 3
find / -maxdepth 1 -newer "$DIR" 2>/dev/null
ls -la /secret.txt 2>&1
